# Yêu cầu gốc: Lấy thông tin phần trăm sử dụng CPU và dung lượng RAM hiện tại (tổng dung lượng, đã dùng, còn trống, phần trăm sử dụng) bằng psutil.

from typing import Any, Dict
import psutil
from core.plugin_manager import export_skill


@export_skill(
    name="get_cpu_and_ram_usage",
    description=(
        "Lấy thông tin chi tiết về phần trăm sử dụng CPU và dung lượng RAM hiện tại của hệ thống (tổng dung lượng, đã dùng, còn trống, phần trăm sử dụng). Các cách người dùng thường yêu cầu: 'kiểm tra tình trạng CPU và RAM', 'xem máy tính đang dùng bao nhiêu RAM', 'kiểm tra hiệu năng máy tính', 'CPU đang chạy bao nhiêu phần trăm', 'xem mức sử dụng tài nguyên hệ thống'. Từ khoá: check CPU usage, RAM usage, system performance, memory stats, monitor system. Ví dụ yêu cầu: «Lấy thông tin phần trăm sử dụng CPU và dung lượng RAM hiện tại (tổng dung lượng, đã dùng, còn trống, phần trăm sử dụng) bằng psutil.»."
    ),
    parameters_schema={
        "type": "object",
        "properties": {
            "interval_seconds": {
                "type": "number",
                "description": "Khoảng thời gian (giây) để đo phần trăm CPU. Mặc định là 0.5 giây.",
                "default": 0.5,
            }
        },
        "required": [],
    },
)
def get_cpu_and_ram_usage(interval_seconds: float = 0.5) -> Dict[str, Any]:
    """
    Thu thập thông tin mức độ sử dụng CPU và RAM bằng psutil.

    Args:
        interval_seconds: Thời gian đo phần trăm CPU (giây).

    Returns:
        Dict[str, Any]: Kết quả chứa thông số chi tiết CPU và RAM hoặc thông báo lỗi.
    """
    try:
        # Giới hạn 0,1–5 s: đo CPU chặn luồng trong suốt khoảng này.
        sample_interval = min(5.0, max(0.1, float(interval_seconds))) if interval_seconds is not None else 0.5

        # Đo mức sử dụng CPU
        cpu_percent = psutil.cpu_percent(interval=sample_interval)
        physical_cores = psutil.cpu_count(logical=False)
        logical_cores = psutil.cpu_count(logical=True)

        # Lấy thông tin bộ nhớ RAM
        virtual_mem = psutil.virtual_memory()
        bytes_to_gb = 1024 ** 3

        total_gb = round(virtual_mem.total / bytes_to_gb, 2)
        used_gb = round(virtual_mem.used / bytes_to_gb, 2)
        available_gb = round(virtual_mem.available / bytes_to_gb, 2)
        free_gb = round(virtual_mem.free / bytes_to_gb, 2)
        ram_percent = virtual_mem.percent

        return {
            "success": True,
            "cpu": {
                "usage_percent": cpu_percent,
                "physical_cores": physical_cores,
                "logical_cores": logical_cores,
            },
            "ram": {
                "total_gb": total_gb,
                "used_gb": used_gb,
                "available_gb": available_gb,
                "free_gb": free_gb,
                "usage_percent": ram_percent,
            },
            "summary": (
                f"CPU: {cpu_percent}% | "
                f"RAM: {used_gb} GB / {total_gb} GB ({ram_percent}%), còn trống {available_gb} GB"
            ),
        }
    except Exception as exc:
        return {
            "success": False,
            "error": f"Không thể lấy thông tin CPU và RAM: {str(exc)}",
            "cpu": None,
            "ram": None,
        }
